use std::{io::Read,sync::{Arc,Mutex}};
#[derive(Default,serde::Serialize)]pub struct Info{pub input_audio:Option<String>,pub decoded_us:Option<u64>,pub speed:Option<String>,pub last_error:Option<String>}
impl Info{fn line(&mut self,s:&str){if s.contains("Stream #0:")&&s.contains("Audio:")&&self.input_audio.is_none(){self.input_audio=Some(s.trim().chars().take(240).collect());}if let Some(v)=s.strip_prefix("out_time_us="){self.decoded_us=v.trim().parse().ok();}if let Some(v)=s.strip_prefix("speed="){self.speed=Some(v.trim().chars().take(24).collect());}if s.contains("Error")||s.contains("Invalid data")||s.contains("Connection refused"){self.last_error=Some(s.trim().chars().take(240).collect());}}}
pub fn watch(mut input:impl Read+Send+'static,info:Arc<Mutex<Info>>){std::thread::spawn(move||{let mut line=Vec::new();let mut chunk=[0;1024];loop{let n=match input.read(&mut chunk){Ok(0)|Err(_)=>break,Ok(n)=>n};for b in &chunk[..n]{if *b==b'\n'{info.lock().unwrap().line(&String::from_utf8_lossy(&line));line.clear();}else if line.len()<4096{line.push(*b);}}}});}
#[cfg(test)]mod tests{use super::*;#[test]fn progress(){let mut i=Info::default();i.line("Stream #0:0: Audio: aac, 44100 Hz, stereo");i.line("out_time_us=1230000");i.line("speed=1.01x");assert_eq!(i.decoded_us,Some(1230000));assert!(i.input_audio.unwrap().contains("aac"));}}
